// Text-Schnappschuss deutscher Seiten (Regression: deutscher Text muss nach dem Übersetzen identisch bleiben).
// node basis.mjs save <ordner> <pfad...>   |   node basis.mjs diff <ordner> <pfad...>
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
const [modus, ordner, ...pfade] = process.argv.slice(2);
mkdirSync(ordner, { recursive: true });
const text = (html) => {
  const m = html.match(/<main[\s\S]*<\/main>/);
  return (m ? m[0] : html)
    .replace(/<script[\s\S]*?<\/script>/g, " ")
    .replace(/<style[\s\S]*?<\/style>/g, " ")
    .replace(/<[^>]+>/g, "\n")
    .split("\n").map((z) => z.trim()).filter(Boolean).join("\n");
};
const head = (html) => [...html.matchAll(/<(title|meta name="description"|link rel="canonical"|meta name="robots")[^>]*>([^<]*)/g)].map((m) => m[0] + m[2]).join("\n");
for (const p of pfade) {
  let html = "";
  for (let v = 0; v < 4; v++) {
    try { html = await (await fetch("http://localhost:3100" + p)).text(); break; } catch { await new Promise((r) => setTimeout(r, 8000)); }
  }
  const datei = `${ordner}/${p.replace(/[^a-z0-9]+/gi, "_") || "start"}.txt`;
  const t = head(html) + "\n----\n" + text(html);
  if (modus === "save") { writeFileSync(datei, t); console.log("gespeichert", p, t.length); continue; }
  if (!existsSync(datei)) { console.log("?? keine Basis", p); continue; }
  const alt = readFileSync(datei, "utf8").split("\n"), neu = t.split("\n");
  const a = new Set(alt), n = new Set(neu);
  const weg = alt.filter((z) => !n.has(z)), dazu = neu.filter((z) => !a.has(z));
  console.log(`${weg.length || dazu.length ? "!!" : "ok"} ${p}  -${weg.length} +${dazu.length}`);
  weg.slice(0, 8).forEach((z) => console.log("   - " + z.slice(0, 150)));
  dazu.slice(0, 8).forEach((z) => console.log("   + " + z.slice(0, 150)));
}

