631	function Tacho({ score, farbe }) {
632	  // Halbkreis 180°, Radius 80. Füllung über stroke-dashoffset (pathLength 100) statt stroke-dasharray –
633	  // nur der Versatz wird animiert (DESIGN § 3.3); unter reduced-motion springt der Wert.
634	  // Ergebnis-Moment: Beim Erscheinen füllt sich der Bogen von 0 und die Zahl zählt mit (rAF, ändert nur den Textknoten).
635	  // Das Server-/Erst-Render enthält bereits den Endwert; ohne JS-Effekt oder bei reduzierter Bewegung bleibt er stehen.
636	  const anteil = Math.max(0, Math.min(100, score));
637	  // Nur den Wert des vorhandenen Textknotens ändern (React behält seinen Knoten)
638	  const zahl = (v) => {
639	    const k = zahlRef.current?.firstChild;
640	    if (k) k.nodeValue = String(v);
641	  };
642	  const zahlRef = useRef(null);
643	  const animiert = useRef(false);
644	  // Start bei 0 (Bogen leer), der Effekt füllt ihn – unter reduzierter Bewegung ohne Übergang (motion-safe)
645	  const [gezeigt, setGezeigt] = useState(0);
646	
647	  useLayoutEffect(() => {
648	    if (animiert.current || window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
649	      setGezeigt(anteil);
650	      zahl(score);
651	      return;
652	    }
653	    zahl(0);
654	    let raf = 0;
655	    let start = 0;
656	    const dauer = 900;
657	    const t0 = window.setTimeout(() => {
658	      animiert.current = true;
659	      setGezeigt(anteil);
660	      const schritt = (t) => {
661	        if (!start) start = t;
662	        const p = Math.min(1, (t - start) / dauer);
663	        zahl(Math.round(score * (1 - Math.pow(1 - p, 3))));
664	        if (p < 1) raf = requestAnimationFrame(schritt);
665	      };
666	      raf = requestAnimationFrame(schritt);
667	    }, 160);
668	    return () => {
669	      window.clearTimeout(t0);
670	      cancelAnimationFrame(raf);
671	      zahl(score);
672	    };
673	    // eslint-disable-next-line react-hooks/exhaustive-deps
674	  }, [score]);
675	
676	  return (
677	    <svg viewBox="0 0 200 116" className="h-auto w-full max-w-[220px]" role="img" aria-label={`Punktwert ${score} von 100`}>
678	      <path d="M20 100 A80 80 0 0 1 180 100" fill="none" stroke="rgba(255,255,255,0.12)" strokeWidth="16" strokeLinecap="round" />
679	      <path
680	        d="M20 100 A80 80 0 0 1 180 100"
681	        fill="none"
682	        stroke={farbe}
683	        strokeWidth="16"
684	        strokeLinecap="round"
685	        pathLength={100}
686	        strokeDasharray="100 100"
687	        strokeDashoffset={100 - gezeigt}
688	        className="motion-safe:transition-[stroke-dashoffset] motion-safe:duration-[900ms] motion-safe:ease-ov-out"
689	      />
690	      <text ref={zahlRef} x="100" y="92" textAnchor="middle" className="fill-white font-display text-[40px] font-extrabold" style={{ fontVariantNumeric: "tabular-nums" }}>{score}</text>
691	      <text x="100" y="112" textAnchor="middle" className="fill-white/75 text-[11px]">von 100 Punkten</text>
692	    </svg>
693	  );
694	}
