// Gruppe 2 (Übersetzung): Seite in 1440 und 390 aufnehmen, in Abschnitte zerlegt, plus Prüfungen.
// Aufruf: node g2-sicht.mjs <basis-url> <ausgabeordner> <pfad> [<pfad> ...]
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const [basis, out, ...pfade] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
for (const pfad of pfade) {
  for (const w of [1440, 390]) {
    const h = w < 700 ? 844 : 900;
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
    // Cookie-Banner vorab als entschieden markieren (nur notwendige)
    await ctx.addInitScript(() => {
      try { localStorage.setItem("ov-cookie", JSON.stringify({ notwendig: true, statistik: false, marketing: false, zeit: Date.now() })); } catch {}
    });
    const page = await ctx.newPage();
    const fehler = [];
    page.on("pageerror", (e) => fehler.push(String(e)));
    page.on("console", (m) => m.type() === "error" && fehler.push(m.text()));
    let status = 0;
    try {
      const r = await page.goto(basis + pfad, { waitUntil: "load", timeout: 180000 });
      status = r?.status() ?? 0;
    } catch (e) {
      console.log(`!! ${pfad} w${w} LADEFEHLER ${String(e).slice(0, 100)}`);
      await ctx.close();
      continue;
    }
    await page.waitForTimeout(1200);
    for (const t of ["Only necessary", "Nur notwendige", "Necessary only"]) await page.locator("button", { hasText: t }).first().click({ timeout: 800 }).catch(() => {});
    const gesamt = await page.evaluate(() => document.documentElement.scrollHeight);
    for (let y = 0; y < gesamt; y += 350) { await page.evaluate((yy) => window.scrollTo(0, yy), y); await page.waitForTimeout(90); }
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.waitForTimeout(700);
    const pruef = await page.evaluate(() => {
      const breite = document.documentElement.scrollWidth;
      // Text, der über seinen Kasten hinausläuft (ohne bewusstes truncate/overflow-x-auto)
      const ueber = [];
      for (const el of document.querySelectorAll("main h1, main h2, main h3, main p, main a, main button, main span, main dt, main dd, main li")) {
        const cs = getComputedStyle(el);
        if (cs.display === "inline" || el.closest("[class*=overflow-x-auto]") || el.className?.toString().includes("truncate") || el.closest(".sr-only") || el.className?.toString().includes("sr-only")) continue;
        if (el.scrollWidth > el.clientWidth + 2 && el.clientWidth > 0 && cs.overflow !== "visible" ) ueber.push((el.innerText || "").slice(0, 60));
        const r = el.getBoundingClientRect();
        if (r.right > window.innerWidth + 1 && r.width > 0 && !el.closest("[class*=overflow-x-auto]") && !el.closest("[class*=overflow-hidden]") && !el.closest("[aria-hidden=true]")) ueber.push("RECHTS: " + (el.innerText || "").slice(0, 60));
      }
      const lang = document.documentElement.lang;
      const hinweis = !!document.querySelector("[data-nicht-uebersetzt]");
      return { breite, ueber: [...new Set(ueber)].slice(0, 8), lang, hinweis };
    });
    const name = pfad.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "start";
    const hoehe = await page.evaluate(() => document.documentElement.scrollHeight);
    const stueck = w < 700 ? 2400 : 2000;
    let n = 0;
    for (let y = 0; y < hoehe; y += stueck) {
      await page.screenshot({ path: `${out}/${name}-w${w}-${String(n++).padStart(2, "0")}.png`, fullPage: true, clip: { x: 0, y, width: w, height: Math.min(stueck, hoehe - y) } });
    }
    const ok = status === 200 && pruef.breite <= w && fehler.length === 0;
    console.log(`${ok ? "ok" : "!!"} ${pfad} w${w} status=${status} lang=${pruef.lang} hinweis=${pruef.hinweis} breite=${pruef.breite} höhe=${hoehe} bilder=${n} fehler=${fehler.length}`);
    pruef.ueber.forEach((u) => console.log("     überlauf? " + u));
    fehler.slice(0, 3).forEach((f) => console.log("     ! " + f.slice(0, 160)));
    await ctx.close();
  }
}
await browser.close();

