    "@context": "https://schema.org",
    "@type": "Service",
    name: w.schema.name,
    serviceType: w.schema.serviceType,
    provider: { "@id": `${SITE.url}/#organization` },
    areaServed: ["DE", "AT", "CH"],
    audience: { "@type": "BusinessAudience", audienceType: w.schema.audience },
    url: abs(PFAD),
    description: w.schema.description,
  };'''),
