613	  // Fläche oberhalb der Grenze = geht in den Speicher
614	  const ueber = pkt.filter((h) => y(solar(h)) < grenze);
615	  const flaeche = `M${x(ueber[0]).toFixed(1)},${grenze} ` + ueber.map((h) => `L${x(h).toFixed(1)},${y(solar(h)).toFixed(1)}`).join(" ") + ` L${x(ueber[ueber.length - 1]).toFixed(1)},${grenze} Z`;
616	  // abends: Speicher speist ein
617	  const abend = `M${x(18)},${basis} L${x(18)},${grenze + 26} Q${x(19.5)},${grenze + 14} ${x(21)},${grenze + 26} L${x(21)},${basis} Z`;
618	  return (
