633	      <line x1="14" x2={W - 14} y1={basis} y2={basis} stroke="#c9d1dc" />
634	      <text x={(x(11) + x(15)) / 2} y={grenze + 20} textAnchor="middle" fontSize="14" fontWeight="700" fill="#03285a">→ Speicher</text>
635	      <text x={x(19.5)} y={grenze + 50} textAnchor="middle" fontSize="13" fontWeight="700" fill="#37521e">abends</text>
