// Fünf Pachtmodelle – Hauptmodell als dunkle Leitkarte mit Laufzeit-Grafik, vier Varianten daneben
import Link from "@/components/Land/Link";
import { ArrowRight, BadgePercent, Banknote, Hammer, Lock, Zap } from "lucide-react";
import SectionHeading from "@/components/ui/SectionHeading";
import Reveal from "@/components/ui/Reveal";
import { fmt, fmtEur } from "@/lib/rechner/annahmen";
import { landHinweisText, pfad, zahlenModus } from "@/lib/land";
import { landDerAnfrage } from "@/lib/land/seite";
import { LandHinweis } from "@/components/Land/LandHinweis";

const tsd = (v) => `${fmt(Math.round(v / 1000))} Tsd. €`;

/** Kumulierte Pacht über die Laufzeit (Säulen) und Einmalzahlung (Linie) */
function LaufzeitGrafik({ jahr, n, einmal }) {
  const max = jahr * n;
  const W = 520;
  const H = 200;
  const b = W / n;
  const yE = H - (einmal / max) * H;
  return (
    <svg viewBox={`0 0 ${W} ${H + 26}`} className="block h-auto w-full" role="img" aria-label={`Kumulierte Pacht über ${n} Jahre bis ${tsd(max)}; die Einmalzahlung von ca. ${tsd(einmal)} entspricht dem Stand nach rund ${fmt(einmal / jahr)} Jahren.`}>
      {[0.25, 0.5, 0.75].map((f) => (
        <line key={f} x1="0" x2={W} y1={H - f * H} y2={H - f * H} stroke="#fff" strokeOpacity="0.08" />
      ))}
      {Array.from({ length: n }, (_, i) => {
        const h = ((i + 1) / n) * H;
        return <rect key={i} x={i * b + 2} y={H - h} width={b - 4} height={h} rx="2.5" fill={i === n - 1 ? "#aed083" : "#669933"} fillOpacity={i === n - 1 ? 1 : 0.55 + (i / n) * 0.35} />;
      })}
      <line x1="0" x2={W} y1={yE} y2={yE} stroke="#ffd873" strokeWidth="1.6" strokeDasharray="6 5" />
      <text x="4" y={yE - 7} fill="#ffd873" fontSize="15" fontWeight="600">Einmalzahlung ca. {tsd(einmal)}</text>
      <text x="2" y={H + 22} fill="#fff" fillOpacity="0.6" fontSize="14">Jahr 1</text>
      <text x={W - 2} y={H + 22} fill="#fff" fillOpacity="0.6" fontSize="14" textAnchor="end">Jahr {n}</text>
    </svg>
  );
}

export default function Modelle({ bsp, dach, m2, stand }) {
  const weitere = [
    { icon: Banknote, t: "Einmalzahlung", k: "Barwert", x: "Alle künftigen Pachten abgezinst auf einen Betrag bei Baubeginn – etwa für Sanierung, Investition oder Tilgung.", s: `ca. ${tsd(bsp.einmalzahlung)} einmalig` },
    { icon: BadgePercent, t: "Umsatzbeteiligung", k: `${fmt(dach.umsatzbeteiligung.min * 100)}–${fmt(dach.umsatzbeteiligung.max * 100)} %`, x: "Anteil an den Stromerlösen, meist mit Mindestpacht. Steigt mit dem Strompreis – schwankt aber mit Ertrag und Markt.", s: `ca. ${fmtEur(bsp.erloesVoll * 0.06)} bei 6 %` },
    { icon: Zap, t: "Dachstrom (PPA)", k: `${fmt(dach.ppaVorOrtCt.min)}–${fmt(dach.ppaVorOrtCt.max)} ct/kWh`, x: "Sie oder Ihr Mieter beziehen den Strom direkt vom Dach – ohne Netzentgelte für diesen Anteil. Pacht dafür meist reduziert.", s: `Barwert ca. ${tsd(bsp.wege.ppa.barwert)} (40 % Eigenverbrauch)` },
    { icon: Hammer, t: "Dachsanierung", k: "als Gegenleistung", x: "Der Betreiber finanziert die Neueindeckung ganz oder teilweise und verrechnet sie mit der Pacht. Sie erhalten ein neues Dach ohne Kapital.", s: `Neueindeckung ≈ ${fmt(bsp.sanierungInPachtjahren, 0)} Pachtjahre` },
  ];

  return (
    <section id="modelle" data-abschnitt="modelle" aria-labelledby="modelle-titel" className="scroll-mt-24 bg-sand-50 py-20 md:py-28">
      <div className="ov-container">
        <SectionHeading
          eyebrow="Fünf Modelle"
          title={<span id="modelle-titel">Pacht, Einmalbetrag, Dachstrom – oder ein neues Dach.</span>}
          lead={`Beispielwerte für ein ${fmt(m2)}-m²-Trapezdach in Süddeutschland (≈ ${fmt(bsp.kwp)} kWp, ${fmt(bsp.kwhJahr1 / 1000)} MWh im Jahr) über ${dach.laufzeit} Jahre. Ihre Werte rechnen Sie im Dachpacht-Rechner.`}
        />

        <div className="mt-10 grid gap-4 md:mt-12 lg:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)]">
          {/* Leitkarte */}
          <Reveal className="ov-verlauf-nacht ov-noise relative flex flex-col overflow-hidden rounded-[1.75rem] p-6 text-white shadow-e3 md:p-8">
            <div aria-hidden="true" className="ov-grid-bg absolute inset-0 opacity-40" />
            <div className="relative flex flex-1 flex-col">
              <div className="flex items-center gap-3">
                <span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-white/10 text-ov-300 ring-1 ring-inset ring-white/15">
                  <Lock aria-hidden="true" className="h-5 w-5" />
                </span>
                <span className="rounded-full bg-ov-300 px-2.5 py-0.5 text-[11px] font-bold uppercase tracking-[0.08em] text-navy-950">Am planbarsten</span>
              </div>
              <h3 className="mt-5 font-display text-[22px] font-bold">Dachpacht fest</h3>
              <p className="ov-num mt-1 font-display text-[30px] font-extrabold leading-tight tracking-tight text-ov-300 md:text-[34px]">
                {fmt(dach.pachtProM2.min, 2)}–{fmt(dach.pachtProM2.max, 2)} €/m²
              </p>
              <p className="mt-3 max-w-md text-[15px] leading-relaxed text-white/75">
                Fester Betrag je m² oder je kWp ({fmt(dach.pachtProKwp.min)}–{fmt(dach.pachtProKwp.max)} €/kWp) und Jahr – auf Wunsch indexiert. Maximal planbar.
              </p>
              <dl className="mt-6 grid grid-cols-3 gap-px overflow-hidden rounded-2xl bg-white/10 ring-1 ring-inset ring-white/10">
                {[
                  ["pro Jahr", fmtEur(bsp.pachtJahr), "text-white"],
                  [`in ${dach.laufzeit} Jahren`, tsd(bsp.wege.pacht.summe), "text-ov-300"],
                  ["Einmalzahlung", `≈ ${tsd(bsp.einmalzahlung)}`, "text-sun-300"],
                ].map(([k, v, c]) => (
                  <div key={k} className="bg-navy-950/60 px-3 py-3 sm:px-4">
                    <dt className="text-[11.5px] leading-tight text-white/60 sm:text-[12px]">{k}</dt>
                    <dd className={`ov-num mt-1 font-display text-[14px] font-extrabold leading-tight sm:text-[18px] ${c}`}>{v}</dd>
                  </div>
                ))}
              </dl>
              <div className="mt-auto pt-6">
                <LaufzeitGrafik jahr={bsp.pachtJahr} n={dach.laufzeit} einmal={bsp.einmalzahlung} />
                <p className="mt-2 text-[12px] text-white/55">Kumulierte Pacht für {fmt(m2)} m² · Linie: Einmalzahlung als Barwert</p>
              </div>
            </div>
          </Reveal>

          {/* Vier Varianten */}
          <ul className="grid gap-4 sm:grid-cols-2">
            {weitere.map((m, i) => (
              <Reveal as="li" key={m.t} delay={80 + i * 60} className="flex flex-col rounded-3xl bg-white p-6 ring-1 ring-ink-200/60">
                <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-ov-50 text-ov-600 ring-1 ring-ov-200">
                  <m.icon aria-hidden="true" className="h-[18px] w-[18px]" />
                </span>
                <h3 className="mt-4 font-display text-[17px] font-bold text-ink-900">{m.t}</h3>
                <p className="ov-num mt-0.5 font-display text-[19px] font-extrabold tracking-tight text-ov-700">{m.k}</p>
                <p className="mt-2.5 text-[14px] leading-relaxed text-ink-600">{m.x}</p>
                <p className="ov-num mt-auto border-t border-ink-100 pt-3.5 text-[13.5px] font-semibold text-ink-800">
                  <span className="sr-only">Beispiel: </span>{m.s}
                </p>
              </Reveal>
            ))}
          </ul>
        </div>

        <div className="mt-8 flex flex-col gap-4 md:flex-row md:items-start md:justify-between md:gap-10">
          {/* Länderinhalt: Beispielwerte gelten für Deutschland – in AT/CH ausdrücklich gesagt (LandHinweis) */}
          {zahlenModus(landDerAnfrage(), ["DE"]) === "hinweis" ? (
            <LandHinweis land={landDerAnfrage()} zeile className="max-w-4xl" text={`Beispielrechnung mit Werten für Deutschland. ${landHinweisText(landDerAnfrage(), "Pacht- und Strompreiswerte")}.`} />
          ) : (
          <p className="max-w-4xl text-[13px] leading-relaxed text-ink-500">
            Nominal und vor Steuern. Einmalzahlung abgezinst mit {fmt(dach.einmalDiskont * 100, 1)} %; Stromerlöse bei Volleinspeisung mit {fmt(dach.eegDachCt, 1)} ct/kWh (Durchschnitt der Dach-Ausschreibungen 2025). Modelle lassen sich kombinieren, etwa Mindestpacht plus Umsatzbeteiligung oder Sanierung plus reduzierte Pacht. Stand {stand}.
          </p>
          )}
          <Link href={pfad("/rechner/dachpacht")} className="group inline-flex shrink-0 items-center gap-2 rounded-full bg-white px-5 py-3 text-[14.5px] font-semibold text-ov-700 shadow-e1 ring-1 ring-ov-200 transition-colors hover:bg-ov-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500">
            Mit eigenen Werten rechnen
            <ArrowRight aria-hidden="true" className="h-4 w-4 transition-transform group-hover:translate-x-0.5 motion-reduce:transition-none" />
          </Link>
        </div>
      </div>
    </section>
  );
}
// Voraussetzungen – vier Prüffragen, Hallenschnitt als Detail, Asbest-Hinweis
import { CalendarClock, Flame, Hammer, PlugZap, Ruler } from "lucide-react";
import SectionHeading from "@/components/ui/SectionHeading";
import Reveal from "@/components/ui/Reveal";
import HallenSchnitt from "@/components/Dach/HallenSchnitt";

export default function Voraussetzungen({ restnutzung }) {
  const fragen = [
    { icon: Ruler, f: "Trägt es?", t: "Statik", x: "Tragreserve für die Zusatzlast der Anlage – je nach Dach und System grob 12–25 kg/m² – plus Schnee- und Windlast am Standort. Nachweis durch einen Tragwerksplaner." },
    { icon: CalendarClock, f: "Hält es lange genug?", t: "Restnutzungsdauer", x: `Die Dachhaut sollte mindestens so lange halten wie der Vertrag – als Faustwert ${restnutzung} Jahre. Sonst zuerst sanieren; das spart später teure Demontagen.` },
    { icon: Flame, f: "Ist der Brandschutz lösbar?", t: "Brandschutz", x: "Abstände zu Brandwänden, Lichtbändern und Rauchabzügen, geprüfte Kabelführung, Abschaltmöglichkeit für die Feuerwehr. Gebäudeversicherer früh einbinden." },
    { icon: PlugZap, f: "Kommt der Strom ins Netz?", t: "Netzanschluss", x: "Freie Kapazität am Hausanschluss oder im Netz in der Nähe. Größere Anlagen brauchen meist eine eigene Übergabestation; die Netzanfrage stellen wir." },
  ];
  return (
    <section data-abschnitt="voraussetzungen" aria-labelledby="voraussetzungen-titel" className="bg-white py-20 md:py-28">
      <div className="ov-container">
        <SectionHeading
          eyebrow="Voraussetzungen"
          title={<span id="voraussetzungen-titel">Was Ihr Dach mitbringen muss.</span>}
          lead="Vier Fragen entscheiden: Trägt es? Hält es lange genug? Ist der Brandschutz lösbar? Kommt der Strom ins Netz? Wir prüfen das mit Ihnen – und sagen offen, wenn ein Dach nicht passt."
        />

        <ol className="mt-10 grid gap-px overflow-hidden rounded-3xl bg-ink-200/70 ring-1 ring-ink-200/70 md:mt-12 sm:grid-cols-2 lg:grid-cols-4">
          {fragen.map((k, i) => (
            <Reveal as="li" key={k.t} delay={i * 70} className="relative flex flex-col bg-white p-6 md:p-7">
              <div className="flex items-center justify-between">
                <span className="ov-num font-display text-[13px] font-bold text-ink-400">0{i + 1}</span>
                <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-ov-50 text-ov-600 ring-1 ring-ov-200">
                  <k.icon aria-hidden="true" className="h-[18px] w-[18px]" />
                </span>
              </div>
              <p className="mt-5 font-display text-[21px] font-bold leading-tight tracking-[-0.01em] text-ink-900">{k.f}</p>
              <p className="mt-1 text-[13px] font-semibold uppercase tracking-[0.1em] text-ov-700">{k.t}</p>
              <p className="mt-3 text-[14.5px] leading-relaxed text-ink-600">{k.x}</p>
            </Reveal>
          ))}
        </ol>

        <Reveal className="mt-6 flex gap-4 rounded-3xl bg-sun-50 p-5 ring-1 ring-sun-200 md:items-center md:p-6">
          <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-sun-300/40 text-sun-700">
            <Hammer aria-hidden="true" className="h-5 w-5" />
          </span>
          <p className="text-[14.5px] leading-relaxed text-ink-700">
            <strong className="text-ink-900">Faserzement-Wellplatten</strong> – bei Gebäuden vor 1993 häufig asbesthaltig – dürfen nicht überbaut oder angebohrt werden. Solche Dächer belegen wir erst nach einer Sanierung. Die Neueindeckung kann Teil des Pachtmodells sein.
          </p>
        </Reveal>

        <div className="mt-14 md:mt-20">
          <div className="mb-6 flex flex-wrap items-end justify-between gap-2">
            <h3 className="ov-h3 text-ink-900">So sitzt eine Anlage auf Ihrer Halle</h3>
            <p className="text-[14px] text-ink-500">Schnitt mit acht Prüfpunkten</p>
          </div>
          <Reveal>
            <HallenSchnitt />
          </Reveal>
        </div>
      </div>
    </section>
  );
}

import { cn } from "@/components/ui/cn";
import Aufbau, { aufbau } from "@/components/Flaeche/Seite/Aufbau";

/**
 * Schnitt durch eine Gewerbehalle mit PV auf dem Dach (Inline-SVG,
 * Server-Komponente). Nummern verweisen auf die Legende – die Grafik bleibt
 * so auch auf dem Handy lesbar.
 */

const LEGENDE = [
  { t: "Module auf dem Dach", x: "Geneigte Dächer parallel belegt, Flachdächer flach Ost/West aufgeständert – mit Ballast oder verklebt, ohne die Dachhaut zu durchdringen, wo möglich." },
  { t: "Statik & Tragreserve", x: "Tragwerksplaner prüft die Zusatzlast (meist ca. 12–25 kg/m²) samt Schnee und Wind. Ohne Reserve keine Belegung." },
  { t: "Dachhaut & Restnutzungsdauer", x: "Das Dach muss die Vertragslaufzeit halten – als Faustwert mindestens 25 Jahre. Sonst zuerst sanieren." },
  { t: "Brandschutzabstände", x: "Freie Streifen an Brandwänden, Lichtbändern und Rauchabzügen; Kabel sauber geführt. Feuerwehr und Versicherer werden früh eingebunden." },
  { t: "Dachzugang & Sicherung", x: "Fester Zugang, Absturzsicherung und Laufwege für Wartung – geregelt im Vertrag mit Anmeldung und Haftung." },
  { t: "Wechselrichter", x: "An der Fassade oder im Technikraum, gut belüftet, zugänglich für Service." },
  { t: "Netzanschluss", x: "Über den vorhandenen Hausanschluss oder eine eigene Übergabestation – bei größeren Anlagen oft Mittelspannung." },
  { t: "Stromverbrauch im Gebäude", x: "Wird der Dachstrom direkt im Gebäude genutzt, ersetzt er teuren Netzstrom – Grundlage für Dachstrom-PPA und Eigenverbrauch." },
];

function Marke({ x, y, n }) {
  return (
    <g className={aufbau.pop} style={{ "--i": n - 1 }}>
      <circle cx={x} cy={y} r="17" className="fill-navy-950" />
      <circle cx={x} cy={y} r="17" fill="none" stroke="#fff" strokeWidth="2.5" />
      <text x={x} y={y + 6} textAnchor="middle" className="fill-white font-display text-[17px] font-extrabold">
        {n}
      </text>
    </g>
  );
}

export default function HallenSchnitt({ className }) {
  // Dach: Pultdach-ähnlich flach geneigt von (160,170) bis (1040,130)
  const dachY = (x) => 170 - ((x - 160) / 880) * 40;
  const reihen = [];
  for (let x = 250; x <= 930; x += 62) {
    if (x > 560 && x < 640) continue; // Brandschutzstreifen / Lichtband
    reihen.push(x);
  }
  return (
    <figure className={cn("overflow-hidden rounded-[2rem] bg-white ring-1 ring-ink-200/70", className)}>
      <div className="bg-gradient-to-b from-navy-50 to-white px-2 pt-4 sm:px-4">
        <Aufbau schritt={70} style={{ "--pop-start": "1250ms", "--pop-schritt": "80ms" }}>
        <svg viewBox="0 0 1200 440" className="block h-auto w-full" role="img" aria-labelledby="halle-titel halle-text">
          <title id="halle-titel">Schnitt durch eine Gewerbehalle mit Photovoltaik auf dem Dach</title>
          <desc id="halle-text">
            Flach geneigtes Hallendach mit Modulreihen, freiem Brandschutzstreifen in der Mitte, Dachzugang mit Geländer, Wechselrichter an der Fassade, Übergabestation und Kabel zum Stromnetz sowie Maschinen im Gebäude als Stromverbraucher.
          </desc>

          {/* Sonne */}
          <circle cx="110" cy="80" r="34" className="fill-sun-300" />
          <circle cx="110" cy="80" r="52" className="fill-sun-300" opacity="0.25" />

          {/* Boden */}
          <rect x="0" y="360" width="1200" height="80" className="fill-ink-100" />
          <rect x="0" y="356" width="1200" height="8" rx="4" className="fill-ink-300" />

          {/* Halle */}
          <polygon points="160,360 160,170 1040,130 1040,360" className="fill-sand-100" />
          <Marke x={600} y={100} n={4} />
          <Marke x={1082} y={110} n={5} />
          <Marke x={240} y={264} n={6} />
          <Marke x={85} y={266} n={7} />
          <Marke x={600} y={268} n={8} />
        </svg>
        </Aufbau>
      </div>
      <figcaption className="border-t border-ink-100 p-5 md:p-7">
        <ol className="grid gap-x-8 gap-y-6 sm:grid-cols-2 lg:grid-cols-4">
          {LEGENDE.map((l, i) => (
            <li key={l.t} className="flex gap-3">
              <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-navy-950 font-display text-[13px] font-extrabold text-white">{i + 1}</span>
              <span className="text-[14px] leading-relaxed text-ink-600">
                <strong className="mb-0.5 block font-display text-[15px] leading-snug text-ink-900">{l.t}</strong>
                {l.x}
              </span>
            </li>
          ))}
        </ol>
      </figcaption>
    </figure>
  );
}

