from ed import R
R("src/components/Dach/HallenSchnitt.js", [
('''import Aufbau, { aufbau } from "@/components/Flaeche/Seite/Aufbau";
''', '''import Aufbau, { aufbau } from "@/components/Flaeche/Seite/Aufbau";
import { spracheDerAnfrage } from "@/lib/land/seite";
import { uebersetze } from "@/lib/sprache/woerterbuch";
'''),
('''function Marke({ x, y, n }) {''', '''/** Sprachmodell: Texte der Grafik (en nur Texte, je Index wie LEGENDE). */
const TEXTE = {
  de: {
