  const faq = inhaltFuerSprache({ de: { gemeinsam: FAQ, AT: FAQ_AT }, en: { gemeinsam: FAQ_EN, AT: FAQ_AT_EN } }, land, sprache);
  const querverweiseAt = sprache === "en" ? QUERVERWEISE_AT.map((q, i) => ({ ...q, ...QUERVERWEISE_AT_EN[i] })) : QUERVERWEISE_AT;
  const schema = {
    "@context": "https://schema.org",
    "@type": "Service",
    name: w.schema.name,
    serviceType: w.schema.serviceType,
    provider: { "@id": `${SITE.url}/#organization` },
