    provider: { "@id": `${SITE.url}/#organization` },
    areaServed: ["DE", "AT", "CH"],
    audience: { "@type": "Audience", audienceType: w.schema.audience },
    url: abs(PFAD),
    description: w.schema.description,
  };'''),
