          "@context": "https://schema.org",
          "@type": "CollectionPage",
          name: "Solarpark & Agri-PV nach Region",
          url: abs(PFAD),
          description: t.beschreibung,
          hasPart: (gemeinsam ? REGIONEN : regionenLand).map((r) => ({ "@type": "WebPage", name: `Solarpark & Agri-PV ${r.inName}`, url: abs(lp(regionSchluessel(r.slug))) })),
        }}
      />

      <Hero
        breadcrumbs={land === "DE" ? [{ name: "Regionen" }] : [{ name: LAND_INFO[land].name, href: LAND_INFO[land].einstieg }, { name: "Regionen" }]}
        pill={gemeinsam ? { marke: "DACH", text: `${REGIONEN.length} Regionalseiten mit Quellen, Stand ${STAND}`, href: "#karte" } : { marke: land, text: `${regionenLand.length} Regionalseiten ${LAND_INFO[land].fuerLand}, Stand ${STAND}`, href: "#karte" }}
        titel={<>Solarpark & <span className="whitespace-nowrap">Agri-PV</span> <span className="ov-text-gradient-light">in Ihrer Region.</span></>}
        lead={<><span className="font-medium text-white">Welche Flächen gehen, was das Land vorschreibt, wie viel die Sonne bringt</span>{deWerte ? " und was an Pacht realistisch ist" : ""} – {t.reichweite}.</>}
        aktionen={[
          { label: "Region wählen", href: "#karte" },
          { label: "Fläche prüfen", href: lp("/flaechencheck") },
        ]}
        hinweis="Für Flächeneigentümer kostenfrei · Einschätzung am Kartentisch"
        versprechen={deWerte ? ["Landesrecht je Region", "Flächenkulisse und Netz", "Ertrag nach PVGIS", "Pacht realistisch eingeordnet"] : ["Landesrecht je Bundesland", "Widmung, Zonen und Netz", "Ertrag nach PVGIS", "Quellen auf jeder Seite"]}
        unten={
          <p className="mt-6 flex items-center gap-2 text-[14px] text-white/70">
            <MapPinned aria-hidden="true" className="h-4 w-4 shrink-0 text-sun-300" />
            <span>Tippen Sie rechts auf Ihre Region – oder <a href="#ertrag" className="rounded font-semibold text-white underline decoration-sun-300/70 underline-offset-4 transition-colors hover:decoration-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-300">vergleichen Sie den Ertrag</a></span>
          </p>
