            ? [
                { wert: fmt(REGIONEN.length), einheit: "Regionen", text: "eigenständig recherchiert, mit Quellen" },
                { wert: `${fmt(ERTRAG_MIN)}–${fmt(ERTRAG_MAX)}`, einheit: "kWh/kWp", text: "spezifischer Ertrag je Region (PVGIS)" },
