function regelnFuer(land) {
  const liste = listeFuerLand(REGELN, land, () => null);
  if (!land || land === "DE") return liste;
  return [...liste, { titel: `Weitere Regeln ${LAENDER[land].inLand}`, text: `${landHinweisText(land, "Regeln zu Direktvermarktung, Netzengpässen und Netzentgelten")}.` }];
}

function faktenFuer(land) {
  const basis = [
    { icon: Clock, wert: "15 min", zahl: { wert: 15, nach: " min" }, einheit: "Viertelstundenraster", text: "Prognosen und Fahrpläne für Parks, Speicher und Verbraucher" },
