    { icon: Radio, wert: "2021", einheit: "Redispatch 2.0", text: "seit Oktober 2021 mit Daten- und Meldepflichten ab 100 kW", nurDE: true },
    { icon: Gauge, wert: "§ 14a", einheit: "EnWG", text: "reduzierte Netzentgelte für steuerbare Verbrauchseinrichtungen", nurDE: true },
  ];
  const liste = listeFuerLand(basis, land, () => null);
  if (!land || land === "DE") return liste;
  return [
    ...liste,
    { icon: Radio, wert: UEBERTRAGUNGSNETZ[land], einheit: "Regelreserve", text: "Ausschreibung durch den Übertragungsnetzbetreiber, mit Präqualifikation" },
    { icon: Gauge, wert: "in Prüfung", einheit: "Vermarktung & Netz", text: landHinweisText(land, "Regeln") },
  ];
}

