function LueckeGrafik() {
  const W = 560;
  const H = 300;
  const L = 16;
  const R = 16;
  const T = 30;
  const B = 250;
  const x = (h) => L + (h / 24) * (W - L - R);
  const n = 97;
  const stunden = Array.from({ length: n }, (_, i) => (i * 24) / (n - 1));
  const solar = (h) => (h < 6 || h > 20 ? 0 : Math.pow(Math.sin(((h - 6) / 14) * Math.PI), 1.5));
