          {!de ? (
            <Reveal dir="right">
              <LandHinweis land={land} thema="Preisbestandteile" className="shadow-xl" />
            </Reveal>
          ) : (
          <Reveal dir="right" className="rounded-[2rem] bg-white p-6 shadow-xl ring-1 ring-ink-200/70 md:p-8">
