"use client";

import { useMemo } from "react";
import Link from "@/components/Land/Link";
import { ArrowRight, BatteryCharging, Factory, LineChart, Timer } from "lucide-react";
import useLiveDaten from "./useLiveDaten";
import { preisTage, zeitfenster, ct, zahl, uhr, berlinTag, stundenmittel, STUNDE } from "./berechnung";
import { pfad } from "@/lib/land";

/**
 * „Was bedeutet das für Sie?" – aus den veröffentlichten Börsenpreisen abgeleitete
 * Hinweise für Unternehmen (Lastverschiebung, Speicher) und Investoren.
 * Bewusst als Orientierung formuliert.
 */
export default function Empfehlungen({ initial }) {
  const { daten, jetzt } = useLiveDaten(initial);
  const tage = useMemo(() => preisTage(daten.preis, jetzt), [daten.preis, jetzt]);

  const horizont = tage.zukunft;
  const speicher = useMemo(() => bestesFenster(tage, horizont, 120), [tage, horizont]);
  const last = useMemo(() => bestesFenster(tage, horizont, 240), [tage, horizont]);
  const heute = tage.heute;
  const guenstig3h = useMemo(() => (heute ? zeitfenster(heute.punkte, 180, tage.schrittMs) : null), [heute, tage.schrittMs]);

  const heuteStr = berlinTag(jetzt);
  const tagWort = (t) => (berlinTag(t) === heuteStr ? "Heute" : "Morgen");

  return (
    <div className="grid gap-4 md:gap-5 lg:grid-cols-2">
      <FensterKarte
        icon={Timer}
        eyebrow="Flexible Last im Betrieb · 4 Stunden"
        fenster={last}
        tagWort={tagWort}
        schrittMs={tage.schrittMs}
        jetzt={jetzt}
        text={(f) =>
          `Im Schnitt ${ct(f.guenstig.avg)} ct/kWh an der Börse. Jede verschobene Megawattstunde – etwa Kühlung, Druckluft oder Chargenprozesse – kostet hier rund ${zahl(Math.max(f.teuer.avg - f.guenstig.avg, 0), 0)} € weniger als im teuersten 4-Stunden-Fenster.`
        }
      />
      <FensterKarte
        icon={BatteryCharging}
        eyebrow="Speicher laden · 2 Stunden"
        fenster={speicher}
        tagWort={tagWort}
        schrittMs={tage.schrittMs}
        jetzt={jetzt}
        text={(f) =>
          `Im Schnitt ${ct(f.guenstig.avg)} ct/kWh – ${ct(f.teuer.avg - f.guenstig.avg)} ct weniger als im teuersten 2-Stunden-Fenster (${uhr(f.teuer.start)}–${uhr(f.teuer.ende)} Uhr). Diese Spanne ist der Rohertrag, den ein Speicher aus einem Zyklus ziehen kann, vor Wirkungsgradverlusten.`
        }
      />

      <LinkKarte
        icon={Factory}
        eyebrow="Unternehmen · Reststrom-Pool"
        titel={guenstig3h ? `Günstigste 3 h heute: ${ct(guenstig3h.guenstig.avg)} ct/kWh netto` : "Börsenpreis gezielt nutzen"}
        text={`${heute ? `Das Tagesmittel liegt bei ${ct(heute.avg)} ct/kWh. ` : ""}Ein Festpreisvertrag gibt Ihnen davon nichts weiter. Im Reststrom-Pool wird gebündelt und in Tranchen beschafft, Solarstrom aus den Parks deckt Tagesstunden – und wer Last verschieben kann, profitiert zusätzlich von günstigen Viertelstunden.`}
        links={[
          { href: pfad("/rechner/reststrom"), label: "Ersparnis berechnen", primaer: true },
          { href: pfad("/reststrom"), label: "Zum Reststrom-Pool" },
        ]}
      />
      <LinkKarte
        dunkel
        icon={LineChart}
        eyebrow="Investoren · Speicher & Solarparks"
        titel={heute ? `Preisspanne heute: ${ct(heute.max.eurMwh - heute.min.eurMwh)} ct/kWh` : "Flexibilität wird zum Erlös"}
        text="Mittags drückt Solarstrom den Preis, abends ist Strom knapp. Genau diese Spanne verdienen Großspeicher – und sie entscheidet, ob ein ungeförderter Solarpark mit Speicher oder PPA wirtschaftlicher ist als ohne."
        links={[
          { href: pfad("/grossspeicher"), label: "Großspeicher", primaer: true },
          { href: "/investoren", label: "Für Investoren" },
        ]}
      />
    </div>
  );
}

/** Ende des Suchzeitraums: Mitternacht als „24:00 Uhr" des Vortags */
function endeLabel(t, tagWort) {
  const u = uhr(t);
  if (u === "00:00") return `${tagWort(t - 1) === "Heute" ? "" : "morgen "}24:00 Uhr`;
  return `${tagWort(t) === "Heute" ? "" : "morgen "}${u} Uhr`;
}

function bestesFenster(tage, horizont, dauerMin) {
  const n = Math.round((dauerMin * 60000) / tage.schrittMs);
  // Genug veröffentlichte Preise ab jetzt? Sonst den heutigen Tag rückblickend zeigen.
  if (horizont.length >= n + 2) return { ...zeitfenster(horizont, dauerMin, tage.schrittMs), punkte: horizont, rueckblick: false };
  if (tage.heute) return { ...zeitfenster(tage.heute.punkte, dauerMin, tage.schrittMs), punkte: tage.heute.punkte, rueckblick: true };
  return null;
}

function FensterKarte({ icon: Icon, eyebrow, fenster, tagWort, text, jetzt }) {
  const ok = fenster?.guenstig && fenster?.teuer;
  const balken = ok ? stundenmittel(fenster.punkte) : [];
  const max = Math.max(...balken.map((b) => b.avg), 1);
  const min = Math.min(0, ...balken.map((b) => b.avg));

  return (
    <article className="flex flex-col rounded-3xl bg-white p-6 ring-1 ring-ink-200/70 md:p-8">
      <div className="flex items-center gap-3">
        <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-ov-50 text-ov-600">
          <Icon aria-hidden="true" className="h-6 w-6" strokeWidth={1.8} />
        </span>
        <p className="text-[12.5px] font-semibold uppercase tracking-[0.14em] text-ink-600">{eyebrow}</p>
      </div>
      {ok ? (
        <>
          <p className="mt-6 text-[14px] text-ink-500">{fenster.rueckblick ? "Günstigste Zeit war heute" : "Beste Startzeit"}</p>
          <h3 className="mt-1 font-display text-[clamp(1.6rem,1.2rem+1.3vw,2.25rem)] font-extrabold leading-tight tracking-tight text-ink-900">
            {fenster.rueckblick ? "" : `${tagWort(fenster.guenstig.start)} `}
            <span className="text-ov-600">
              {uhr(fenster.guenstig.start)}–{uhr(fenster.guenstig.ende)} Uhr
            </span>
          </h3>
          <p className="mt-3 text-[15.5px] leading-relaxed text-ink-600">{text(fenster)}</p>

          {/* Mini-Balken: Stundenpreise im Suchzeitraum, Fenster hervorgehoben */}
          <div className="mt-auto pt-7" aria-hidden="true">
            <div className="flex h-16 items-end gap-[2px]">
              {balken.map((b) => {
                const imFenster = b.t + STUNDE > fenster.guenstig.start && b.t < fenster.guenstig.ende;
                const h = Math.max(((b.avg - min) / (max - min)) * 100, 4);
                return (
                  <span
                    key={b.t}
                    className={`min-w-0 flex-1 rounded-t-[3px] ${imFenster ? "bg-ov-500" : b.t <= jetzt && jetzt < b.t + STUNDE ? "bg-ink-500" : "bg-ink-200"}`}
                    style={{ height: `${h}%`, maxWidth: 24 }}
                  />
                );
              })}
            </div>
            <div className="mt-2 flex justify-between text-[12px] text-ink-500">
              <span>{fenster.rueckblick ? "0 Uhr" : "jetzt"}</span>
              <span>
                {balken.length ? endeLabel(balken[balken.length - 1].t + STUNDE, tagWort) : ""}
              </span>
            </div>
          </div>
        </>
      ) : (
        <p className="mt-6 text-[15.5px] leading-relaxed text-ink-600">
          Sobald die Börsenpreise wieder abrufbar sind, zeigen wir hier die günstigste Zeit. Faustregel: an sonnigen Tagen mittags, an windigen
          Tagen oft nachts – teuer ist es meist zwischen 18 und 21 Uhr.
        </p>
      )}
    </article>
  );
}

function LinkKarte({ icon: Icon, eyebrow, titel, text, links, dunkel }) {
  return (
    <article
      className={`relative flex flex-col overflow-hidden rounded-3xl p-6 md:p-8 ${
        dunkel ? "bg-navy-950 text-white" : "bg-ov-50 ring-1 ring-ov-200/70"
      }`}
    >
      {dunkel && <div aria-hidden="true" className="absolute -right-24 -top-24 h-64 w-64 rounded-full bg-ov-500/25 blur-[90px]" />}
      <div className="relative flex items-center gap-3">
        <span className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl ${dunkel ? "bg-white/10 text-ov-300" : "bg-white text-ov-600"}`}>
          <Icon aria-hidden="true" className="h-6 w-6" strokeWidth={1.8} />
        </span>
        <p className={`text-[12.5px] font-semibold uppercase tracking-[0.14em] ${dunkel ? "text-white/60" : "text-ink-600"}`}>{eyebrow}</p>
      </div>
      <h3 className={`relative mt-6 font-display text-[clamp(1.35rem,1.1rem+0.9vw,1.75rem)] font-extrabold leading-tight tracking-tight ${dunkel ? "text-white" : "text-ink-900"}`}>
        {titel}
      </h3>
      <p className={`relative mt-3 text-[15.5px] leading-relaxed ${dunkel ? "text-white/70" : "text-ink-600"}`}>{text}</p>
      <div className="relative mt-auto flex flex-col gap-3 pt-7 sm:flex-row sm:flex-wrap">
        {links.map((l) => (
          <Link
            key={l.href}
            href={l.href}
            className={`group inline-flex h-12 items-center justify-center gap-2 rounded-full px-6 text-[15px] font-semibold transition-all ${
              l.primaer
                ? "bg-ov-600 text-white hover:bg-ov-700"
                : dunkel
                  ? "text-white ring-1 ring-inset ring-white/35 hover:bg-white/10"
                  : "bg-white text-ink-900 ring-1 ring-inset ring-ink-200 hover:ring-ink-300"
            }`}
          >
            {l.label}
            {l.primaer && <ArrowRight aria-hidden="true" className="h-4 w-4 transition-transform group-hover:translate-x-1" />}
          </Link>
        ))}
      </div>
    </article>
  );
}
import { QUELLEN } from "./berechnung";

const farbe = (key) => QUELLEN.find((q) => q.key === key)?.farbe;

// Schematische Angebotskurve: Breite = verfügbare Leistung, Höhe = Grenzkosten.
// Bewusst ohne Zahlen – es geht um das Prinzip, nicht um exakte Werte.
const BLOECKE = [
  { name: "Wind & Solar", breite: 38, hoehe: 3, farbe: farbe("windOnshore") },
  { name: "Wasser & Biomasse", breite: 10, hoehe: 20, farbe: farbe("biomasse") },
  { name: "Braunkohle", breite: 13, hoehe: 40, farbe: farbe("braunkohle") },
  { name: "Steinkohle", breite: 10, hoehe: 56, farbe: farbe("steinkohle") },
  { name: "Erdgas", breite: 20, hoehe: 78, farbe: farbe("gas") },
  { name: "Öl & Reserve", breite: 9, hoehe: 100, farbe: "#97a0b0" },
];

const NACHFRAGE = [
  { nr: 1, pos: 30, titel: "Sonniger, windiger Mittag", text: "Wind und Solar decken fast alles – der Preis bleibt niedrig, bei Überschuss sogar negativ." },
  { nr: 2, pos: 84, titel: "Windstiller Winterabend", text: "Gaskraftwerke werden gebraucht – ihr teurer Strom setzt den Preis für alle." },
];

/** Merit-Order als responsive HTML-Grafik (keine skalierte Schrift, lesbar auf dem Smartphone). */
export default function MeritOrder() {
  return (
    <figure className="rounded-[2rem] bg-white p-5 text-ink-900 shadow-2xl sm:p-8">
      <figcaption className="flex flex-wrap items-baseline justify-between gap-2">
        <span className="font-display text-[18px] font-bold">Merit-Order – so entsteht der Börsenpreis</span>
        <span className="text-[12.5px] text-ink-500">schematisch</span>
      </figcaption>

      <div className="relative mt-8 flex">
        {/* y-Achsenbeschriftung */}
        <div className="mr-2 flex w-5 shrink-0 items-center justify-center">
          <span className="-rotate-90 whitespace-nowrap text-[11.5px] text-ink-500">Grenzkosten →</span>
        </div>
        <div className="relative h-56 flex-1 border-b border-l border-ink-300 sm:h-64">
          <div className="absolute inset-0 flex items-end gap-[2px] pl-[2px]">
            {/* Einlauf (über das umgebende Reveal): Kraftwerksblöcke wachsen in Merit-Order-Reihenfolge –
                billig links zuerst –, danach erscheinen die beiden Nachfrage-Szenarien */}
            {BLOECKE.map((b, i) => (
              <div
                key={b.name}
                className="ov-balken-y rounded-t-[4px]"
                style={{ width: `calc(${b.breite}% - 2px)`, height: `${Math.max(b.hoehe, 3)}%`, background: b.farbe, "--i": i * 2 }}
                title={b.name}
              />
            ))}
          </div>
          {NACHFRAGE.map((n) => (
            <div key={n.nr} className="ov-flaeche-ein absolute inset-y-0" style={{ left: `${n.pos}%`, animationDelay: `${750 + n.nr * 220}ms` }}>
              <div className="absolute -top-3 bottom-0 w-0 border-l-2 border-ink-900" />
              <span className="absolute -top-6 flex h-6 w-6 -translate-x-1/2 items-center justify-center rounded-full bg-ink-900 text-[12px] font-bold text-white ring-2 ring-white">
                {n.nr}
              </span>
            </div>
          ))}
        </div>
      </div>
      <p className="mt-2 text-right text-[11.5px] text-ink-500">verfügbare Kraftwerksleistung →</p>

      <ul className="mt-4 flex flex-wrap gap-x-4 gap-y-2 text-[13px] text-ink-600">
        {BLOECKE.map((b) => (
          <li key={b.name} className="flex items-center gap-2">
            <span aria-hidden="true" className="h-3 w-3 rounded-[3px]" style={{ background: b.farbe }} />
            {b.name}
          </li>
        ))}
      </ul>

      <ol className="mt-6 grid gap-3 border-t border-ink-100 pt-6 sm:grid-cols-2">
        {NACHFRAGE.map((n) => (
          <li key={n.nr} className="flex gap-3">
            <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-ink-900 text-[12px] font-bold text-white">{n.nr}</span>
            <span className="text-[14px] leading-snug text-ink-600">
              <strong className="block text-ink-900">{n.titel}</strong>
              {n.text}
            </span>
          </li>
        ))}
      </ol>
    </figure>
  );
}

