  const w = TEXTE[en ? "en" : "de"];
  const { fmt } = useFormate();
  const euro = useEuro();
  const ctaLabel = ctaLabelProp ?? w.ctaLabel;
  const [e, setE] = useState({ ...RECHNER_STANDARD });
  const set = (k) => (v) => setE((a) => ({ ...a, [k]: v }));
