  const modellLabel = (id) => (en ? MODELLE_EN[id]?.label : null) ?? RECHNER_MODELLE[id].label;'''),
('''  const regelJahr = e.jahr === 2027 ? "ab 2027" : "2026";
  const ansage = `${r.nettoEur < 0 ? "Nachteil" : "Vorteil"} netto ${euro(Math.abs(r.nettoEur))} pro Jahr${vorstand ? " je Mitglied" : ""}${verbraucht ? `, ${fmt(r.quotePct)} Prozent des Verbrauchs aus der Gemeinschaft` : ""}, ${RECHNER_MODELLE[e.modell].label}, Regeln ${regelJahr}.`;''', '''  const regelJahr = e.jahr === 2027 ? w.ab2027 : "2026";
  const ansage = w.ansage(r.nettoEur < 0, euro(Math.abs(r.nettoEur)), vorstand, verbraucht ? fmt(r.quotePct) : null, modellLabel(e.modell), regelJahr);'''),
('''  const deckungOptionen = opt(RECHNER_DECKUNG).map((o) => ({ ...o, sub: o.sub?.replace(/^Erzeugung\\s*/, "").replace(/\\s*des Verbrauchs$/, "") }));''', '''  const deckungOptionen = en
    ? optEn(RECHNER_DECKUNG, true, DECKUNG_EN)
    : opt(RECHNER_DECKUNG).map((o) => ({ ...o, sub: o.sub?.replace(/^Erzeugung\\s*/, "").replace(/\\s*des Verbrauchs$/, "") }));'''),
('''<MobilKurz werte={[["Vorteil netto", euro(r.nettoEur)], ["aus Gemeinschaft", `${fmt(r.quotePct)} %`], ["CO₂", `${fmt(r.co2Kg)} kg`]]} />
          <Ueberschrift className="sr-only">{vorstand ? "Angaben zum Beispielmitglied" : "Ihre Angaben"}</Ueberschrift>''', '''<MobilKurz werte={[[w.mobilVorteil, euro(r.nettoEur)], [w.mobilAus, `${fmt(r.quotePct)} %`], ["CO₂", `${fmt(r.co2Kg)} kg`]]} />
          <Ueberschrift className="sr-only">{vorstand ? w.angabenV : w.angaben}</Ueberschrift>'''),
('''<Gruppe titel={<Schritt n={1}>{vorstand ? "Beispielmitglied" : "Sie"}</Schritt>}>''', '''<Gruppe titel={<Schritt n={1}>{vorstand ? w.beispielmitglied : w.sie}</Schritt>}>'''),
('''{verbraucht && <Auswahl legende="Verbrauch" wert={e.profil} onChange={set("profil")} optionen={opt(RECHNER_PROFILE)} spalten={2} klein />}
