                        </span>'''),
('''<span className="mt-0.5 block text-[12.5px] leading-snug text-ink-500">Vorbelegt mit üblichen Werten – anpassen, wenn Sie Ihre Preise kennen.</span>''', '''<span className="mt-0.5 block text-[12.5px] leading-snug text-ink-500">{w.vorbelegt}</span>'''),
('''<Regler label="Energiepreis Ihres Lieferanten"''', '''<Regler label={w.lieferant}'''),
('''hinweis="nur Energieanteil, ohne Netz und Abgaben" />}''', '''hinweis={w.lieferantH} />}'''),
('''<Regler label="Preis in der Gemeinschaft"''', '''<Regler label={w.gemPreis}'''),
('''hinweis="üblich 9–14 ct (Marktbeobachtung)" />}''', '''hinweis={w.gemPreisH} />}'''),
('''<Regler label="Netznutzungs-Arbeitspreis"''', '''<Regler label={w.netzAp}'''),
('''hinweis="je Netzgebiet verschieden, siehe Netzrechnung" />}''', '''hinweis={w.netzApH} />}'''),
('''<Regler label="Einspeisepreis der Gemeinschaft"''', '''<Regler label={w.einspeise}'''),
('''<Regler label="Alternative: Marktpreis Überschuss"''', '''<Regler label={w.markt}'''),
('''<Regler label="Gebühren und Beitrag" wert={e.gebuehrenJahr} min={0} max={150} step={5} format={(v) => `${fmt(v)} €/Jahr`} onChange={set("gebuehrenJahr")} />''', '''<Regler label={w.gebuehren} wert={e.gebuehrenJahr} min={0} max={150} step={5} format={(v) => w.eurJahr(fmt(v))} onChange={set("gebuehrenJahr")} />'''),
('''md:text-[26px]">{vorstand ? "Ergebnis je Mitglied" : "Ihr Ergebnis"}</Ueberschrift>''', '''md:text-[26px]">{vorstand ? w.ergebnisV : w.ergebnis}</Ueberschrift>'''),
('''              {RECHNER_MODELLE[e.modell].label} · {regelJahr}''', '''              {modellLabel(e.modell)} · {regelJahr}'''),
('''                  {vorstand ? "Vorteil netto je Mitglied und Jahr" : "Vorteil netto pro Jahr"}''', '''                  {vorstand ? w.vorteilJahrV : w.vorteilJahr}'''),
('''<Zahl wert={r.nettoEur} suffix=" €" delta="dunkel" deltaFormat={(d) => `${fmt(Math.round(d))} €`} />''', '''<Zahl wert={r.nettoEur} prefix={en ? "€" : ""} suffix={en ? "" : " €"} delta="dunkel" deltaFormat={(d) => w.eur(fmt(Math.round(d)))} />'''),
('''<p className="mt-2 text-[13.5px] leading-snug text-white/75">nach {fmt(r.gebuehrenEur)} € Gebühren und Beitrag</p>''', '''<p className="mt-2 text-[13.5px] leading-snug text-white/75">{w.nach(w.eur(fmt(r.gebuehrenEur)))}</p>'''),
