// Sucht deutsche Textreste im <main> einer englischen Seite. Aufruf: node deutsch.mjs <url> [...]
const DE = /[äöüÄÖÜß]|\b(und|der|die|das|mit|für|nicht|oder|wir|Sie|Ihre?|eine?|auf|ist|sind|werden|bei|nach|vom|zum|zur|über|auch|wird|wie|Fläche|Pacht)\b/;
const ERLAUBT = /ÖkoInvest|ÖKOVOLT|Ökovolt|Österreich-Glossar|Widmung|Grünland|Bürgschaft|Flächenkulisse|Gemeinde|BauGB|Länd|Ostermiething|Deutsche Fassung|Baugesetzbuch|Raumplanungsgesetz|Bundesnetzagentur|Bundesland|Niederösterreich|Oberösterreich|Kärnten|Thüringen|Baden-Württemberg|Zürich|Graubünden|Solarpaket|Freiflächen|Erneuerbaren|Gesetz/;
for (const url of process.argv.slice(2)) {
  const html = await (await fetch(url, { headers: { cookie: "" } })).text();
  let m = html.match(/<main[\s\S]*<\/main>/);
  let t = (m ? m[0] : html).replace(/<script[\s\S]*?<\/script>/g, " ").replace(/<style[\s\S]*?<\/style>/g, " ")
    .replace(/<[^>]+>/g, "\n").replace(/&nbsp;|&#x27;|&quot;|&amp;/g, (x) => ({ "&nbsp;": " ", "&#x27;": "'", "&quot;": '"', "&amp;": "&" })[x]);
  const zeilen = [...new Set(t.split("\n").map((z) => z.trim()).filter((z) => z.length > 2 && DE.test(z)))];
  const rest = zeilen.filter((z) => !(ERLAUBT.test(z) && !/\b(und|der|die|mit|für|Sie|wir|ist)\b/.test(z)));
  console.log(`== ${url}  ${rest.length} verdächtige Zeilen`);
  rest.slice(0, 80).forEach((z) => console.log("  " + z.slice(0, 160)));
}

