        <rect width="560" height="480" rx="32" fill="#fbfaf6" />

        {/* Mitglieder */}
        {[
          { x: 70, t: "Bürger" },
          { x: 210, t: "Landwirte" },
          { x: 350, t: "Gemeinden" },
          { x: 490, t: "Betriebe" },
