// Prüft die englischen Regionsdateien gegen die deutschen: gleiche Listenlängen, keine fremden Schlüssel.
// Aufruf (im Projektordner): node <pfad>/pruefe-regionen.mjs
import { readdirSync } from "node:fs";
import { pathToFileURL } from "node:url";
const basis = "C:/Users/SALEADMIN/Downloads/Oekoinvest-Web/src/data/regionen/";
const dateien = readdirSync(basis + "en").filter((f) => f.endsWith(".js") && f !== "index.js");
let fehler = 0;
const vergleiche = (de, en, pfad) => {
  if (en === undefined || en === null) return;
  if (Array.isArray(en)) {
    if (!Array.isArray(de)) { console.log(`!! ${pfad}: en ist Liste, de nicht`); fehler++; return; }
    if (de.length !== en.length) { console.log(`!! ${pfad}: Länge de ${de.length} / en ${en.length}`); fehler++; }
    en.forEach((x, i) => vergleiche(de[i], x, `${pfad}[${i}]`));
    return;
  }
  if (typeof en === "object") {
    if (typeof de !== "object" || de === null) { console.log(`!! ${pfad}: en ist Objekt, de nicht`); fehler++; return; }
    for (const k of Object.keys(en)) {
      if (!(k in de)) { console.log(`!! ${pfad}.${k}: Schlüssel fehlt im Deutschen`); fehler++; continue; }
      vergleiche(de[k], en[k], `${pfad}.${k}`);
    }
    return;
  }
  if (typeof en === "string" && /[äöüß]/.test(en) && !/Ö|Baden-Württemberg|Gäu|Würzburg|Börde|Jülich|Zülpich|Fläming|Dübener|Mönchengladbach|Kärnten|Grafschaft|Lübeck|Neumünster|Georgswerder|Rendsburg|Löbau|Niederösterreich|Oberösterreich|„|Thüringer|Mühl|Wörther|Graubünden|Zürich|Thür/.test(en)) {
    console.log(`?  ${pfad}: Umlaut im englischen Text: ${en.slice(0, 90)}`);
  }
};
for (const f of dateien) {
  const de = (await import(pathToFileURL(basis + f).href)).default;
  const en = (await import(pathToFileURL(basis + "en/" + f).href)).default;
  vergleiche(de, en, f.replace(".js", ""));
  const pflicht = ["seoTitel", "beschreibung", "lead", "akzent", "einleitung", "recht", "agri", "faq"];
  for (const k of pflicht) if (de[k] && !en[k]) { console.log(`!! ${f}: ${k} fehlt in en`); fehler++; }
  for (const k of ["kulisse", "ablauf", "besonderheiten", "pacht", "kantone"]) if (de[k] && !en[k]) { console.log(`!! ${f}: ${k} fehlt in en`); fehler++; }
}
console.log(`${dateien.length} Regionen geprüft, ${fehler} Fehler`);

