  "/bedingungen/lieferanten": VERMERK_EN_RECHT,
  "/bedingungen/banken": VERMERK_EN_RECHT,
  // Gruppe 3 – Rechner und Marktdaten
  "/rechner": VERMERK_EN_G3,
  "/rechner/pacht": VERMERK_EN_G3,
  "/rechner/agri-pv": VERMERK_EN_G3,
